package br.com.ajudamutua.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="outbox_events") public class OutboxEvent { @Id private UUID id; @Column(nullable=false,length=80) private String aggregateType; private UUID aggregateId; @Column(nullable=false,length=80) private String eventType; @Column(nullable=false,columnDefinition="TEXT") private String payload; @Column(nullable=false) private Instant createdAt; private Instant publishedAt; @Column(nullable=false) private int attempts; protected OutboxEvent(){} public OutboxEvent(UUID id,String aggregateType,UUID aggregateId,String eventType,String payload,Instant createdAt){this.id=id;this.aggregateType=aggregateType;this.aggregateId=aggregateId;this.eventType=eventType;this.payload=payload;this.createdAt=createdAt;} public UUID getId(){return id;} public String getEventType(){return eventType;} public String getPayload(){return payload;} public Instant getPublishedAt(){return publishedAt;} public void markPublished(){publishedAt=Instant.now();attempts++;} public void markAttempt(){attempts++;} }
